export function stoppedValue(v){const sd=seed(v),n=integer(v,'dyadic level n',0,8,4),S=panel(v,'Values at strict-up approximations'),T=panel(v,'Approximated stopped values','level n','B(Sₙ)');let h,sn,bn,vals;
 v.render(()=>{const p=H.brownian(sd.value,9,2);h=H.stopped(p,-.5,.5,.8);sn=H.strictRound(h.time,n.value);bn=H.at(p,sn);vals=H.lin(0,8,8).map(j=>[j,H.at(p,H.strictRound(h.time,j))]);fit(S,[p]);line(S,p);S.dot(h.time,h.value,{color:'green',r:6});S.dot(sn,bn,{color:'orange',r:5});fit(T,[vals,[[0,h.value],[8,h.value]]]);line(T,vals,'orange');T.hline(h.value,{color:'green',dash:true});});legend(v,[['accent','finite interpolation'],['green','B(S) at a capped exit'],['orange','B(Sₙ)']]);v.readout(()=>`S≈${f(h.time)}, Sₙ=${f(sn)}; B(S)≈${f(h.value)}, B(Sₙ)≈${f(bn)}. Continuity drives convergence. For each fixed m, every later approximation is F_{S_m}-measurable, so the limit is measurable in their intersection F_S. Values between displayed nodes use interpolation.`);}
export function strongMarkov(v){const sd=seed(v),mode=v.select('restart rule',['first hit of a','last zero before 1'],'first hit of a'),a=slider(v,'hitting level a',.1,1,.4),S=panel(v,'Restarted polygonal continuations','time after chosen restart','increment'),T=panel(v,'Finite-window restart counts','status','count');let count,total,after;
 v.render(()=>{a.el.hidden=mode.value!=='first hit of a';const segments=[];count=0;total=36;after=[];for(let j=0;j<total;j++){const p=H.brownian(sd.value+71*j,9,2),hit=mode.value==='first hit of a'?H.hit(p,a.value):{time:H.crossings(p.filter(q=>q[0]<=1)).at(-1)??0,value:0};if(hit&&hit.time<=1){count++;segments.push([[0,0],...p.filter(q=>q[0]>hit.time&&q[0]<=hit.time+.5).map(([t,b])=>[t-hit.time,b-hit.value])]);after.push(H.at(p,Math.min(hit.time+.25,2))-hit.value);}}fit(S,[...segments,[[0,0],[.5,0]]]);segments.slice(0,12).forEach(p=>line(S,p,'accent',{alpha:.6,width:1}));bars(T,[count,total-count]);});legend(v,[['accent','at most 12 displayed continuations / observed restarts'],['orange','restarters excluded by time cutoff']]);v.readout(()=>`${count}/${total} polygonal restart times are ≤1. ${mode.value==='first hit of a'?'The genuine Brownian stopping time has fresh Brownian increments by strong Markov. Polygonal hits introduce a finite-mesh error.':'A last zero depends on the future: its post-time path is selected by avoiding another zero before 1. The strong Markov conclusion cannot be applied to this restart.'} ${after.length?statLabel(v,after):'No qualifying restarts.'}`);}

export function passageProcess(v){const sd=seed(v),a=slider(v,'maximum level a',.2,1.5,1),S=panel(v,'Brownian interpolation and selected levels'),T=panel(v,'First passages as the level increases','level','first passage time');let times;
 v.render(()=>{const p=H.brownian(sd.value,10,8),levels=H.lin(0,a.value,20);times=levels.map(x=>[x,H.hit(p,x)?.time??null]);fit(S,[p,[[0,a.value],[8,a.value]]]);line(S,p);for(const level of[a.value/2,a.value])S.hline(level,{color:'orange',dash:true});fit(T,[times.filter(q=>q[1]!==null),[[0,0],[a.value,8]]]);line(T,times.filter(q=>q[1]!==null),'orange');dots(T,times.filter(q=>q[1]!==null),'gold');});legend(v,[['accent','finite path'],['orange','levels / polygonal first passages'],['gold','observed levels']]);v.readout(()=>`${times.filter(q=>q[1]!==null).length}/21 selected levels hit by time 8; omitted levels are censored. The theorem gives stationary independent increments in the level parameter and Tₐ distributed as a²T₁. This finite curve neither proves independence nor resolves excursion jumps of the continuum first-passage process.`);}
export function reflection(v){const sd=seed(v),a=slider(v,'positive level a',.1,1.5,.5),time=slider(v,'time horizon t',.1,2,1),S=panel(v,'Reflect after the first polygonal hit'),T=panel(v,'Exact-law probability curves','time','probability');let d;
 v.render(()=>{const p=H.brownian(sd.value,9,time.value);d=H.reflect(p,a.value);fit(S,[p,d.path,[[0,a.value],[time.value,a.value]]]);line(S,p);line(S,d.path,'orange');S.hline(a.value,{color:'green',dash:true});if(d.hit)S.dot(d.hit.time,a.value,{color:'gold',r:5});T.setView([-.15,2.2],[-.15,1.15]);line(T,H.lin(0,2).map(t=>[t,H.hitCDF(a.value,t)]));line(T,H.lin(0,2).map(t=>[t,H.hitCDF(a.value,t)/2]),'orange');T.dot(time.value,H.hitCDF(a.value,time.value),{color:'gold',r:5});});legend(v,[['accent','original / P(Tₐ≤t)'],['orange','reflected / P(Bₜ≥a)'],['green','level a'],['gold','selected hit / probability']]);v.readout(()=>`P(Tₐ≤t)=2P(Bₜ≥a)≈${f(H.hitCDF(a.value,time.value))}; normal CDF evaluated numerically. ${d.hit?`First polygonal hit ${f(d.hit.time)}.`:'No hit detected on the polygon by the horizon.'} Reflection of the genuine path preserves Brownian law; reflecting a sampled polygon illustrates the mapping with approximate crossing times.`);}
export function arcsine(v){const sd=seed(v),n=integer(v,'grid level',4,9,7),s=slider(v,'last-zero cutoff s',0,1,.3),S=panel(v,'A path and its last polygonal zero'),T=panel(v,'Last-zero distribution','cutoff s','CDF');let last,empirical;
 v.render(()=>{const p=H.brownian(sd.value,n.value);last=H.crossings(p).at(-1)??0;fit(S,[p]);line(S,p);S.dot(last,0,{color:'gold',r:6});const samples=Array.from({length:160},(_,j)=>H.crossings(H.brownian(sd.value+79*j,n.value)).at(-1)??0).sort((a,b)=>a-b);empirical=samples.filter(x=>x<=s.value).length/samples.length;T.setView([-.12,1.12],[-.15,1.15]);line(T,H.lin(0,1).map(x=>[x,H.arcsineCDF(x)]),'orange');line(T,steps(samples.map((x,i)=>[x,(i+1)/samples.length]),0,1));T.dot(s.value,H.arcsineCDF(s.value),{color:'gold',r:5});});legend(v,[['accent','finite path / empirical CDF'],['orange','exact arcsine CDF'],['gold','last polygonal zero / selected exact CDF']]);v.readout(()=>`Last polygonal zero ${f(last)}. At s=${f(s.value)}, exact CDF ${f(H.arcsineCDF(s.value))}; 160-path sampled fraction ${f(empirical)}. Finite interpolation misses unsampled zero crossings. This law is for the LAST ZERO before 1, not the occupation time above zero.`);}

export function optionalStopping(v){const sd=seed(v),a=slider(v,'exit radius',.15,1.5,.6),mode=v.select('rule',['first grid exit, capped at 1','grid maximum (looks ahead)'],'first grid exit, capped at 1'),S=panel(v,'A selected path and its chosen node'),T=panel(v,'Mean of 180 selected values','sample prefix','mean');let values,chosen;
 v.render(()=>{a.el.hidden=!mode.value.startsWith('first');const paths=Array.from({length:180},(_,j)=>H.brownian(sd.value+83*j,7));values=paths.map(p=>{const z=mode.value.startsWith('first')?(p.find(q=>Math.abs(q[1])>=a.value)??p.at(-1)):p.reduce((best,q)=>q[1]>best[1]?q:best,p[0]);return z;});chosen=values[0];fit(S,[paths[0]]);line(S,paths[0]);S.dot(...chosen,{color:'gold',r:6});let sum=0;const means=values.map((q,i)=>[i+1,(sum+=q[1])/(i+1)]);fit(T,[means]);line(T,means,'orange');T.hline(0,{color:'green',dash:true});});legend(v,[['accent','sampled path'],['gold','chosen grid node'],['orange','running sample average'],['green','initial mean 0']]);v.readout(()=>`${mode.value.startsWith('first')?'The first grid exit, capped at 1, is an actual bounded stopping time for the sampled Brownian motion. Its value can overshoot the boundary.':'Choosing the maximum needs future values and is not a stopping rule; its expected value is positive.'} Selected time ${f(chosen[0])}; sample mean ${f(H.mean(values.map(q=>q[1])))}. A finite average is not forced to equal the theoretical mean.`);}
export function brownianMartingale(v){const sd=seed(v),x=slider(v,'current Bₛ',-1.5,1.5,.5),h=slider(v,'remaining duration',0,2,.7),S=panel(v,'Future endpoint values','sample','endpoint'),T=panel(v,'Conditional mean identity','term','value');let a;
 v.render(()=>{const rng=H.random(sd.value);a=Array.from({length:80},()=>x.value+Math.sqrt(h.value)*H.normal(rng));fit(S,[a.map((y,i)=>[i,y])]);dots(S,a.map((y,i)=>[i,y]));S.hline(x.value,{color:'orange',dash:true});bars(T,[x.value,H.mean(a),Math.sqrt(h.value)]);});legend(v,[['accent','conditional endpoints / current state'],['orange','conditional mean / sample average'],['green','conditional standard deviation']]);v.readout(()=>`E[Bₛ₊ₕ | Fₛ]=Bₛ=${f(x.value)} and conditional variance h=${f(h.value)}. The sample average is ${f(H.mean(a))}. The third bar is √h, not a mean. At h=0 every sample equals the known state exactly.`);}
export function exitProbability(v){const sd=seed(v),left=slider(v,'left boundary a',-2,-.2,-1),right=slider(v,'right boundary b',.2,2,1),fraction=slider(v,'starting fraction in interval',0,1,.4),S=panel(v,'Exact exit-probability functions','position','probability'),T=panel(v,'Polygonal exits before time 8','outcome','fraction');let x,law,counts;
 v.render(()=>{x=left.value+fraction.value*(right.value-left.value);law=H.exitLaw(left.value,right.value,x);S.setView([left.value-.2,right.value+.2],[-.15,1.15]);line(S,[[left.value,1],[right.value,0]]);line(S,[[left.value,0],[right.value,1]],'orange');S.dot(x,law.left,{color:'gold',r:5});counts=[0,0,0];for(let j=0;j<120;j++){const p=H.brownian(sd.value+89*j,9,8,x),d=H.stopped(p,left.value,right.value,8);counts[!d.exited?2:d.value===left.value?0:1]++;}probabilities(T,counts.map(c=>c/120));});legend(v,[['accent','left exit'],['orange','right exit / unresolved bars'],['gold','selected exact left probability']]);v.readout(()=>`x=${f(x)}; exact P(left)=${f(law.left)}, P(right)=${f(law.right)}. Sample counts: left ${counts[0]}, right ${counts[1]}, no polygonal exit by 8: ${counts[2]}. All bar fractions use denominator 120. Missed between-node exits cause discretization bias; censored paths are not discarded. At a boundary the exit time is 0.`);}
export function squareMartingale(v){const sd=seed(v),x=slider(v,'current Bₛ',-1.5,1.5,.5),s=slider(v,'current time s',0,1,.3),h=slider(v,'future duration h',0,1.5,.7),S=panel(v,'Conditional second-moment balance','term','value'),T=panel(v,'Monte Carlo mean of Bₜ²−t','sample prefix','mean');let a;
 v.render(()=>{bars(S,[x.value*x.value,h.value,x.value*x.value+h.value]);const rng=H.random(sd.value);a=Array.from({length:160},()=>{const b=x.value+Math.sqrt(h.value)*H.normal(rng);return b*b-s.value-h.value;});let sum=0;const ps=a.map((y,i)=>[i+1,(sum+=y)/(i+1)]);fit(T,[ps,[[1,x.value*x.value-s.value],[160,x.value*x.value-s.value]]]);line(T,ps);T.hline(x.value*x.value-s.value,{color:'orange',dash:true});});legend(v,[['accent','Bₛ² / sampled martingale mean'],['orange','increment variance h / exact conditional value'],['green','E[Bₛ₊ₕ² | Fₛ]']]);v.readout(()=>`Exact second-moment identity: ${f(x.value*x.value)}+${f(h.value)}=${f(x.value*x.value+h.value)}. Subtracting s+h leaves Bₛ²−s=${f(x.value*x.value-s.value)}. Sample mean ${f(H.mean(a))}; it fluctuates rather than staying exactly at the theoretical value.`);}
export function exitMean(v){const sd=seed(v),a=slider(v,'left magnitude −a',.2,2,1),b=slider(v,'right boundary b',.2,2,1.4),horizon=slider(v,'finite observation horizon',.5,8,4),S=panel(v,'Mean exit time as a function of the start','position x','EₓT'),T=panel(v,'Capped polygonal exit times','sample','time');let vals,censored;
 v.render(()=>{const left=-a.value,ps=H.lin(left,b.value).map(x=>[x,(x-left)*(b.value-x)]);fit(S,[ps]);line(S,ps);S.dot(0,a.value*b.value,{color:'gold',r:6});vals=[];censored=0;for(let j=0;j<100;j++){const d=H.stopped(H.brownian(sd.value+97*j,9,horizon.value),left,b.value,horizon.value);vals.push(d.time);if(!d.exited)censored++;}fit(T,[vals.map((y,i)=>[i,y])]);dots(T,vals.map((y,i)=>[i,y]),'orange',3);});legend(v,[['accent','exact mean (x−a)(b−x)'],['gold','start 0: −ab'],['orange','100 capped polygonal exit times']]);v.readout(()=>`Exact E₀T=−ab=${f(a.value*b.value)}. Capped polygonal mean ${f(H.mean(vals))}; ${censored}/100 paths have no detected exit before ${f(horizon.value)}. Capping and missed between-node crossings both affect this estimate; it is not presented as an unbiased mean or a certified bound.`);}
export function exponential(v){const sd=seed(v),theta=slider(v,'parameter θ',-2,2,1),S=panel(v,'Exponential martingales','time','value'),T=panel(v,'Exact mean and median','time','value');let final;
 v.render(()=>{const ps=Array.from({length:12},(_,j)=>H.brownian(sd.value+101*j,7).map(([t,b])=>[t,Math.exp(theta.value*b-theta.value*theta.value*t/2)]));fit(S,ps);ps.forEach(p=>line(S,p,'accent',{alpha:.5,width:1}));final=ps.map(p=>p.at(-1)[1]);const median=H.lin(0,1).map(t=>[t,Math.exp(-theta.value*theta.value*t/2)]);T.setView([-.12,1.12],[-.15,1.3]);line(T,[[0,1],[1,1]],'orange');line(T,median,'green');});legend(v,[['accent','12 seeded path transforms'],['orange','exact mean 1'],['green','exact median exp(−θ²t/2)']]);v.readout(()=>`At time 1 the 12-path mean is ${f(H.mean(final))}; the exact expectation is 1, and the exact median is ${f(Math.exp(-theta.value*theta.value/2))}. Rare large values can dominate the mean. θ=0 gives the constant process; almost-sure decay as t→∞ requires θ≠0.`);}
export function hittingLaplace(v){const sd=seed(v),a=slider(v,'positive hit level a',.1,2,.8),lambda=slider(v,'Laplace parameter λ',0,3,.6),S=panel(v,'Laplace transform in λ','λ','transform'),T=panel(v,'Exact-law sample terms exp(−λTₐ)','sample','value');let vals;
 v.render(()=>{S.setView([-.2,3.2],[-.15,1.15]);line(S,H.lin(0,3).map(l=>[l,H.laplaceHit(a.value,l)]));S.dot(lambda.value,H.laplaceHit(a.value,lambda.value),{color:'gold',r:5});const rng=H.random(sd.value);vals=Array.from({length:180},()=>{const z=H.normal(rng);return lambda.value===0?1:z===0?0:Math.exp(-lambda.value*(a.value/z)**2);});fit(T,[vals.map((y,i)=>[i,y])]);dots(T,vals.map((y,i)=>[i,y]),'orange');});legend(v,[['accent','exact transform exp(−a√(2λ))'],['gold','selected exact value'],['orange','180 exact-law draws (up to PRNG rounding)']]);v.readout(()=>`Exact transform ${f(H.laplaceHit(a.value,lambda.value))}; sample mean ${f(H.mean(vals))}. Here Tₐ is sampled as a²/Z² with Z standard normal, using the reflection-principle law; no path-grid hitting approximation is used. At λ=0 every term is exactly 1.`);}
export function polynomials(v){const sd=seed(v),order=integer(v,'polynomial degree',1,4,3),s=slider(v,'current time s',0,1,.3),x=slider(v,'current state x',-1.2,1.2,.5),S=panel(v,'Space-time harmonic polynomial','x','u(t,x)'),T=panel(v,'Conditional average at s+½','sample prefix','mean');let vals,target;
 v.render(()=>{const ps=H.lin(-1.5,1.5).map(y=>[y,H.heatPolynomial(order.value,s.value,y)]),qs=H.lin(-1.5,1.5).map(y=>[y,H.heatPolynomial(order.value,s.value+.5,y)]);fit(S,[ps,qs]);line(S,ps);line(S,qs,'orange');S.dot(x.value,H.heatPolynomial(order.value,s.value,x.value),{color:'gold',r:5});const rng=H.random(sd.value);vals=Array.from({length:200},()=>H.heatPolynomial(order.value,s.value+.5,x.value+Math.SQRT1_2*H.normal(rng)));let sum=0;target=H.heatPolynomial(order.value,s.value,x.value);const means=vals.map((z,i)=>[i+1,(sum+=z)/(i+1)]);fit(T,[means,[[1,target],[200,target]]]);line(T,means);T.hline(target,{color:'green',dash:true});});legend(v,[['accent','u(s,x) / sample mean'],['orange','u(s+½,x)'],['gold','current state'],['green','exact conditional expectation']]);v.readout(()=>`Degree ${order.value}: uₜ+½uₓₓ=0. Exact conditional expectation u(s,x)=${f(target)}; sample mean ${f(H.mean(vals))}. The offered polynomials are x, x²−t, x³−3tx, and x⁴−6tx²+3t². Polynomial growth supplies all required Gaussian moments.`);}
export function secondExitMoment(v){const a=slider(v,'symmetric exit radius a',.2,2,1),x=slider(v,'starting location / a',-1,1,0),S=panel(v,'First and second exit moments','start / a','normalised moment'),T=panel(v,'Fourth-degree stopped identity at start 0','term','value');let m1,m2;
 v.render(()=>{const ps=H.lin(-1,1).map(u=>[u,1-u*u]),qs=H.lin(-1,1).map(u=>[u,(5-6*u*u+u**4)/3]);fit(S,[ps,qs]);line(S,ps);line(S,qs,'orange');S.dot(x.value,(5-6*x.value*x.value+x.value**4)/3,{color:'gold',r:5});m1=a.value*a.value*(1-x.value*x.value);m2=a.value**4*(5-6*x.value*x.value+x.value**4)/3;bars(T,[a.value**4,-6*a.value**4,5*a.value**4]);});legend(v,[['accent','EₓT/a² / a⁴'],['orange','EₓT²/a⁴ / −6a²E₀T'],['green','3E₀T²'],['gold','selected second moment']]);v.readout(()=>`At x=${f(a.value*x.value)}, EₓT=${f(m1)}, EₓT²=${f(m2)}. The right bars sum to zero: a⁴−6a²·a²+3·(5a⁴/3)=0. At the center, E₀T²=5a⁴/3=${f(5*a.value**4/3)}. The off-center quartic follows by solving ½m₂″=−2m₁ with zero boundary values; it is not a simulated estimate.`);}

function itoPanels(v,title){return[panel(v,title),panel(v,'Final decomposition','term','value')];}
export function itoFormula(v){const sd=seed(v),kind=v.select('function',['square','cube','sine'],'square'),n=integer(v,'dyadic level',2,10,7),[S,T]=itoPanels(v,'Function change and Itô sum');let d;
 v.render(()=>{const p=H.coarse(H.brownian(sd.value,10),n.value);d=H.ito(p,kind.value);const actual=d.rows.map(q=>[q[0],q[1]]),sum=d.rows.map(q=>[q[0],q[2]+q[3]]);fit(S,[actual,sum]);line(S,actual);line(S,sum,'orange');bars(T,[d.actual,d.stochastic,d.drift,d.residual],['accent','orange','green','purple']);});legend(v,[['accent','actual f(B) change'],['orange','Itô sum / stochastic term'],['green','½f″ time sum'],['purple','residual']]);v.readout(()=>`${2**n.value} intervals; actual change ${f(d.actual)}, left-point stochastic sum ${f(d.stochastic)}, drift sum ${f(d.drift)}, residual ${f(d.residual)}. Refinements reuse the same dyadic samples; the residual need not decrease at each level. Finite left-point sums approximate the Itô integral, not the ordinary integral along the interpolating polygon.`);}
export function weakIntegrands(v){const sd=seed(v),n=integer(v,'dyadic level',2,10,6),mode=v.select('integrand',['continuous weight','zero-measure limit'],'continuous weight'),S=panel(v,'Cumulative quadratic-variation measure','time','mass'),T=panel(v,'Weighted integrals under refinement','level','integral');let data;
 v.render(()=>{const fine=H.brownian(sd.value,10),scale=mode.value==='zero-measure limit'?2**(-n.value):1,p=H.coarse(fine,n.value);let mass=0;const cumulative=[[0,0]];for(let i=1;i<p.length;i++){mass+=(p[i][1]-p[i-1][1])**2*scale;cumulative.push([p[i][0],mass]);}fit(S,[cumulative,[[0,0],[1,scale]]]);line(S,steps(cumulative,0,1));line(S,[[0,0],[1,scale]],'orange');data=H.lin(2,10,8).map(k=>{const q=H.coarse(fine,k);let sum=0;for(let i=1;i<q.length;i++){const t=q[i][0];sum+=(1+t+2**(-k)*Math.sin(2*Math.PI*t))*(q[i][1]-q[i-1][1])**2;}return[k,sum*(mode.value==='zero-measure limit'?2**(-k):1)];});fit(T,[data,[[2,mode.value==='zero-measure limit'?0:1.5],[10,mode.value==='zero-measure limit'?0:1.5]]]);line(T,data,'green');T.hline(mode.value==='zero-measure limit'?0:1.5,{color:'orange',dash:true});});legend(v,[['accent','atomic squared-increment mass'],['orange','scaled Lebesgue reference / weighted limit'],['green','weighted sums']]);v.readout(()=>`gₙ(t)=1+t+2⁻ⁿ sin(2πt) converges uniformly to g(t)=1+t. Selected weighted integral ${f(data[n.value-2][1])}; limit ${mode.value==='zero-measure limit'?'0 as total mass vanishes':'∫₀¹(1+t)dt=1.5'}. The lemma includes zero finite measures; its proof need not divide by total mass. This finite experiment does not certify weak convergence.`);}
export function stochasticIntegral(v){const sd=seed(v),n=integer(v,'dyadic level',2,9,7),mode=v.select('integrand g',['one','x'],'x'),S=panel(v,'Left-point stochastic-integral samples'),T=panel(v,'Finite-sum mean and second moment','statistic','value');let finals,varianceExact;
 v.render(()=>{const paths=[];finals=[];for(let j=0;j<160;j++){const p=H.brownian(sd.value+103*j,n.value),out=[[0,0]];let sum=0;for(let i=1;i<p.length;i++){sum+=(mode.value==='one'?1:p[i-1][1])*(p[i][1]-p[i-1][1]);out.push([p[i][0],sum]);}if(j<8)paths.push(out);finals.push(sum);}fit(S,paths);paths.forEach(p=>line(S,p,'accent',{alpha:.6,width:1}));varianceExact=mode.value==='one'?1:(1-2**(-n.value))/2;bars(T,[H.mean(finals),H.mean(finals.map(x=>x*x)),varianceExact],['orange','accent','green']);});legend(v,[['accent','eight finite-sum paths / empirical second moment'],['orange','empirical mean'],['green','exact discrete second moment']]);v.readout(()=>`Sample mean ${f(H.mean(finals))}; second moment ${f(H.mean(finals.map(x=>x*x)))}. Exact discrete isometry gives ${f(varianceExact)}; the continuous-integral second moment is ${mode.value==='one'?'1':'½'}. For g=x, the difference is the missing left-endpoint rectangle area, 1/(2·2ⁿ). Integrability is required for a true martingale; continuity alone gives a local martingale.`);}
export function timeFormula(v){const sd=seed(v),mu=slider(v,'time exponent μ',-1,1,-.5),sigma=slider(v,'space exponent σ',0,1.5,1),n=integer(v,'dyadic level',2,10,7),[S,T]=itoPanels(v,'Exponential function and time-dependent Itô sum');let d;
 v.render(()=>{d=H.timeIto(H.coarse(H.brownian(sd.value,10),n.value),mu.value,sigma.value);const a=d.rows.map(q=>[q[0],q[1]]),b=d.rows.map(q=>[q[0],q[2]+q[3]]);fit(S,[a,b]);line(S,a);line(S,b,'orange');bars(T,[d.actual,d.stochastic,d.drift],['accent','orange','green']);});legend(v,[['accent','actual exp(μt+σB) change'],['orange','stochastic sum / total reconstruction'],['green','drift time sum']]);v.readout(()=>`Drift coefficient μ+σ²/2=${f(d.coefficient)}. Actual change ${f(d.actual)}, stochastic sum ${f(d.stochastic)}, drift sum ${f(d.drift)}, residual ${f(d.actual-d.stochastic-d.drift)}. Zero drift occurs at μ=−σ²/2; the sign is positive in the generator. Parameters are not rounded to force cancellation.`);}
export function multidimensional(v){const sd=seed(v),kind=v.select('function',['squared radius','product xy'],'squared radius'),n=integer(v,'dyadic level',2,10,7),S=panel(v,'Two-dimensional sampled Brownian path','x','y',{equal:true}),T=panel(v,'Function and stochastic decomposition','time','value');let d;
 v.render(()=>{const p=H.coarse(H.brownian(sd.value,10),n.value),q=H.coarse(H.brownian(sd.value+10007,10),n.value);d=H.ito2(p,q,kind.value==='squared radius'?'radius':'product');const xy=p.map((z,i)=>[z[1],q[i][1]]);fit(S,[xy]);line(S,xy);S.dot(...xy.at(-1),{color:'gold',r:6});const a=d.rows.map(z=>[z[0],z[1]]),b=d.rows.map(z=>[z[0],z[2]+z[3]]);fit(T,[a,b]);line(T,a);line(T,b,'orange');});legend(v,[['accent','sampled path / actual function change'],['orange','stochastic terms plus Laplacian drift'],['gold','last point']]);v.readout(()=>`Actual change ${f(d.actual)}; stochastic sum ${f(d.stochastic)}; drift ${f(d.drift)}; residual ${f(d.actual-d.stochastic-d.drift)}. Cross-variation sum ΣΔB¹ΔB²=${f(d.cross)}. ${kind.value==='squared radius'?'Δ(x²+y²)=4, so the drift is 2t.':'Δ(xy)=0, but the finite residual is exactly the cross-variation sum.'} The two coordinate generators use distinct seeds; ideal coordinates are independent.`);}
